// Grouped from 5 flat commands (Poll/slashcommand-giveaway-end.js, Poll/slashcommand-giveaway-list.js, Poll/slashcommand-giveaway.js, Poll/slashcommand-poll.js, Poll/slashcommand-reroll.js). Generated by scripts/group-commands.js.
const { ChatInputCommandInteraction } = require('discord.js');
const DiscordBot = require('../../client/DiscordBot');
const ApplicationCommand = require('../../structure/ApplicationCommand');
const { t, resolveLocale } = require('../../utils/i18n');
const { PermissionFlagsBits } = require('discord.js');
const { successEmbed, errorEmbed, infoEmbed } = require('../../utils/embeds');

const SUB_PERMS = {
    "giveaway": "32",
    "giveaway-end": "32",
    "reroll": "32",
};

const handlers = {
    "giveaway": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const modstore = require('../../utils/modstore');
        const prize = interaction.options.getString('prize', true);
        const minutes = Math.max(1, interaction.options.getInteger('minutes', true));
        const winners = Math.max(1, interaction.options.getInteger('winners') || 1);
        const msg = await interaction.reply({ content: '**' + prize + '**\n' + t('giveaway.ends', { locale, vars: { m: minutes } }), fetchReply: true });
        try { await msg.react('🎉'); } catch {}
        const rec = modstore.push(client.database, 'giveaways', interaction.guildId, { channelId: msg.channelId, messageId: msg.id, prize, winners, endsAt: Date.now() + minutes * 60000, ended: false });
        require('../../utils/scheduler').scheduleKind(client, interaction.guildId, 'giveaway', { giveawayId: rec.id }, rec.endsAt);
        return undefined;
    },
    "giveaway-end": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const id = interaction.options.getInteger('id', true);
        const arr = client.database.get('giveaways-' + interaction.guildId) || [];
        const g = arr.find(x => x.id === id);
        if (!g) return interaction.reply({ embeds: [errorEmbed(locale, t('giveaway.notfound', { locale }))], ephemeral: true });
        g.ended = true;
        client.database.set('giveaways-' + interaction.guildId, arr);
        try {
            const ch = await client.channels.fetch(g.channelId).catch(() => null);
            const m = ch ? await ch.messages.fetch(g.messageId).catch(() => null) : null;
            const users = m ? [...(await m.reactions.resolve('🎉')?.users.fetch().catch(() => new Map()))?.values() || []].filter(u => !u.bot) : [];
            const wins = users.sort(() => Math.random() - 0.5).slice(0, g.winners || 1);
            if (ch && ch.isTextBased()) await ch.send(wins.length ? t('giveaway.won', { locale, vars: { users: wins.map(u => '<@' + u.id + '>').join(' '), prize: g.prize } }) : t('giveaway.nobody', { locale }));
        } catch {}
        return interaction.reply({ embeds: [successEmbed(locale, t('giveaway.ended', { locale, vars: { id } }))] });
    },
    "giveaway-list": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const modstore = require('../../utils/modstore');
        const list = modstore.all(client.database, 'giveaways', interaction.guildId);
        if (!list.length) return interaction.reply({ embeds: [infoEmbed(locale, t('giveaway.empty', { locale }))], ephemeral: true });
        return interaction.reply({ embeds: [infoEmbed(locale, list.slice(-10).map(g => '#' + g.id + ' ' + g.prize + ' (' + (g.ended ? 'ended' : 'open') + ')').join('\n'))] });
    },
    "poll": async (client, interaction) => {
        const q = interaction.options.getString('question', true);
        const opts = interaction.options.getString('options', true).split(';').map(s => s.trim()).filter(Boolean).slice(0, 10);
        const nums = ['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];
        const msg = await interaction.reply({ content: '**' + q + '**\n' + opts.map((o, i) => nums[i] + ' ' + o).join('\n'), fetchReply: true });
        for (let i = 0; i < opts.length; i++) { try { await msg.react(nums[i]); } catch {} }
        return undefined;
    },
    "reroll": async (client, interaction) => {
        const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
        const id = interaction.options.getInteger('id', true);
        const arr = client.database.get('giveaways-' + interaction.guildId) || [];
        const g = arr.find(x => x.id === id);
        if (!g) return interaction.reply({ embeds: [errorEmbed(locale, t('giveaway.notfound', { locale }))], ephemeral: true });
        try {
            const ch = await client.channels.fetch(g.channelId).catch(() => null);
            const m = ch ? await ch.messages.fetch(g.messageId).catch(() => null) : null;
            const users = m ? [...(await m.reactions.resolve('🎉')?.users.fetch().catch(() => new Map()))?.values() || []].filter(u => !u.bot) : [];
            const wins = users.sort(() => Math.random() - 0.5).slice(0, g.winners || 1);
            if (ch && ch.isTextBased()) await ch.send(wins.length ? t('giveaway.won', { locale, vars: { users: wins.map(u => '<@' + u.id + '>').join(' '), prize: g.prize } }) : t('giveaway.nobody', { locale }));
        } catch {}
        return interaction.reply({ embeds: [successEmbed(locale, t('giveaway.rerolled', { locale, vars: { id } }))] });
    },
};

module.exports = new ApplicationCommand({
    command: {
        name: "giveaway", description: "🎉 Giveaways and polls.", type: 1,
        description_localizations: { 'pt-BR': "🎉 Sorteios e enquetes." },
        options: [
            {
                name: "giveaway",
                description: "🎉 Creates a giveaway (minutes + winners).",
                description_localizations: {"pt-BR":"🎉 Cria sorteio (minutos + ganhadores)."},
                type: 1,
                options: [{"name":"prize","name_localizations":{"pt-BR":"premio"},"description":"Prize","description_localizations":{"pt-BR":"Prêmio"},"type":3,"required":true},{"name":"minutes","name_localizations":{"pt-BR":"minutos"},"description":"Duration minutes","description_localizations":{"pt-BR":"Duração em minutos"},"type":4,"required":true},{"name":"winners","name_localizations":{"pt-BR":"ganhadores"},"description":"Winners count","description_localizations":{"pt-BR":"Qtd ganhadores"},"type":4}],
            },
            {
                name: "giveaway-end",
                description: "🎉 Ends a giveaway now.",
                description_localizations: {"pt-BR":"🎉 Encerra um sorteio agora."},
                type: 1,
                options: [{"name":"id","description":"Giveaway ID","description_localizations":{"pt-BR":"ID do sorteio"},"type":4,"required":true}],
            },
            {
                name: "giveaway-list",
                description: "🎉 Lists giveaways.",
                description_localizations: {"pt-BR":"🎉 Lista sorteios."},
                type: 1,
                options: [],
            },
            {
                name: "poll",
                description: "📊 Creates a poll (up to 10 options).",
                description_localizations: {"pt-BR":"📊 Cria enquete (até 10 opções)."},
                type: 1,
                options: [{"name":"question","name_localizations":{"pt-BR":"pergunta"},"description":"Question","description_localizations":{"pt-BR":"Pergunta"},"type":3,"required":true},{"name":"options","name_localizations":{"pt-BR":"opcoes"},"description":"opt1; opt2; ... (max 10)","description_localizations":{"pt-BR":"opc1; opc2; ... (máx 10)"},"type":3,"required":true}],
            },
            {
                name: "reroll",
                description: "🎉 Rerolls a giveaway winner.",
                description_localizations: {"pt-BR":"🎉 Sorteia de novo um ganhador."},
                type: 1,
                options: [{"name":"id","description":"Giveaway ID","description_localizations":{"pt-BR":"ID do sorteio"},"type":4,"required":true}],
            },
        ],
    },
    /**
     * @param {DiscordBot} client
     * @param {ChatInputCommandInteraction} interaction
     */
    run: async (client, interaction) => {
        const sub = interaction.options.getSubcommand();
        const need = SUB_PERMS[sub];
        if (need) {
            let ok = false;
            try { ok = !!interaction.memberPermissions && interaction.memberPermissions.has(BigInt(need)); } catch { ok = false; }
            if (!ok) {
                const locale = resolveLocale({ guildId: interaction.guildId, discordLocale: interaction.locale });
                return interaction.reply({ content: t('handler.missing_permissions', { locale }), ephemeral: true });
            }
        }
        const fn = handlers[sub];
        if (!fn) {
            return interaction.reply({ content: 'Unknown subcommand: ' + sub, ephemeral: true });
        }
        return fn(client, interaction);
    },
}).toJSON();
